import axios from 'axios';
import React, { Component } from 'react';
import MyContext from '../contexts/MyContext';
import './ChatAdmin.css';

class ChatAdmin extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      chats: [],
      selectedCustomer: null,
      newMessage: ''
    };
  }

  render() {
    if (this.context.token === '') return null;

    const customers = [...new Set(this.state.chats.map(chat => chat.customer._id))].map(id => {
      const chat = this.state.chats.find(c => c.customer._id === id);
      return chat.customer;
    });

    const messages = this.state.selectedCustomer
      ? this.state.chats.filter(chat => chat.customer._id === this.state.selectedCustomer._id)
      : [];

    return (
      <div className="chat-admin-container">
        <h2>Admin Chat Support</h2>
        <div className="chat-admin-content">
          <div className="customer-list">
            <h3>Customers</h3>
            {customers.map(customer => (
              <div
                key={customer._id}
                className={`customer-item ${this.state.selectedCustomer && this.state.selectedCustomer._id === customer._id ? 'active' : ''}`}
                onClick={() => this.setState({ selectedCustomer: customer })}
              >
                {customer.name} ({customer.username})
              </div>
            ))}
          </div>
          <div className="chat-window">
            {this.state.selectedCustomer ? (
              <>
                <h3>Chat with {this.state.selectedCustomer.name}</h3>
                <div className="messages">
                  {messages.map((msg, index) => (
                    <div key={index} className={`message ${msg.sender}`}>
                      <strong>{msg.sender === 'customer' ? msg.customer.name : 'Admin'}:</strong> {msg.message}
                    </div>
                  ))}
                </div>
                <div className="message-input">
                  <input
                    type="text"
                    value={this.state.newMessage}
                    onChange={(e) => this.setState({ newMessage: e.target.value })}
                    placeholder="Type your response..."
                  />
                  <button onClick={this.sendMessage}>Send</button>
                </div>
              </>
            ) : (
              <p>Select a customer to start chatting.</p>
            )}
          </div>
        </div>
      </div>
    );
  }

  componentDidMount() {
    this.apiGetChats();
  }

  apiGetChats = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/chats', config).then((res) => {
      this.setState({ chats: res.data });
    });
  };

  sendMessage = () => {
    if (!this.state.selectedCustomer || this.state.newMessage.trim() === '') return;
    const config = { headers: { 'x-access-token': this.context.token } };
    const body = {
      customerId: this.state.selectedCustomer._id,
      message: this.state.newMessage
    };
    axios.post('/api/admin/chat', body, config).then((res) => {
      this.setState({ newMessage: '' });
      this.apiGetChats(); // Refresh
    });
  };
}

export default ChatAdmin;
